INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (153, 193, 'BOPP Matte film (15,18,20 microns) matt Polypropylene film', '../', '<p></p><p>BOPP Matte film (15,18,20 microns) matt Polypropylene film</p> <p>BOPP Matte film were like paper and kerchief.<br/> Thickness:12,15,17,18,20,25,30,35 microns <br/> Width: 325-1800MM Length :3000-9000M <br/> Inner paper tube core :3"(76MM) ,6" (152MM)<br/> Character: : Inner side matte (as its standard), Two side corona treated . <br/> BOPP matte film (inner side BOPP matte film) included 15 microns bopp matte film, 18microns Polypropylene matte film, 20microns BOPP matte laminating film <br/> BOPP film,Polypropylene film,BOPP FOIL,OPP packing film, BOPP printing film, BOPP matte film, BOPP thermal film,OPP heat sealable film,corona treated film, 28 microns tape film , bopp bag film ,bopp glossy film, bopp pearlized film ,bopp metallize film,bopp white film, bopp food package film, bopp anti static film,<br/> Low gloss and high haze; perfect printing performance ;excellent heat sealing performance.<br/> Assumes the diffuse reflection, the eye feeling is gentle, the printing effect is good, completely obviously noble, comfortable feel well, if the paper resembles the silk, the other side features same printable &amp;composite. Application : Laminate with paper for book or magazine, gift bags too , As well can be used for package box of soap ,food ,cigarette ,cosmetics and medical products.</p> <p><br/></p>', '2026-09-06 20:58:45');